import Foundation
import CoreGraphics
import CoreImage
import CryptoKit

/// CI-only strict comparison. References are freshly generated by importing
/// ORIGINAL src/spektrafilm/model/couplers.py, not computed with Swift logic.
/// These are multi-size whole-frame SPATIAL-DIR stage comparisons; not proof
/// of source stochastic grain, RAW, full film->print spectral RGB or iPhone GPU.
enum SourceFullFrameParity {
    enum Failure: LocalizedError {
        case invalid(String)
        var errorDescription: String? {
            if case .invalid(let message) = self { return message }
            return nil
        }
    }
    private struct Manifest: Decodable {
        let scope: String
        let source: String
        let cases: [Sample]
    }
    private struct Sample: Decodable {
        let name: String
        let film: String
        let positive: Bool
        let width: Int
        let height: Int
        let pixelUM: Double
        let radiusScale: Double
        let tailWeight: Double
        let matrix: [Double]
        let densityMaximum: [Double]
        let sha256: [String: String]
    }
    private struct Metrics {
        var maxError = 0.0
        var squaredError = 0.0
        var sumError = 0.0
        var worst = 0
        var length = 0

        mutating func compare(
            _ observed: [Double], reference: [Double], label: String
        ) throws {
            guard observed.count == reference.count, !observed.isEmpty else {
                throw Failure.invalid("\(label): Python and Swift dimensions differ")
            }
            length = observed.count
            for i in observed.indices {
                guard observed[i].isFinite && reference[i].isFinite else {
                    throw Failure.invalid("\(label): NaN/Inf at RGB channel \(i)")
                }
                let delta = abs(observed[i] - reference[i])
                sumError += delta
                squaredError += delta * delta
                if delta > maxError {
                    maxError = delta
                    worst = i
                }
            }
            let mae = sumError / Double(length)
            let rmse = sqrt(squaredError / Double(length))
            // This tolerance is about Float32 identity-LUT *nodes* and
            // image ingress; all DIR physical filtering is Swift Double.
            guard maxError <= 2e-5 && mae <= 2e-6 else {
                throw Failure.invalid(
                    "\(label): FAIL source original full-frame stage; " +
                    "MAE=\(mae), RMSE=\(rmse), max=\(maxError), " +
                    "worst pixel=\(worst/3), channel=\(worst%3). " +
                    "No precision certification."
                )
            }
            print(
                "PASS \(label) source pixels=\(length/3), MAE=\(mae), " +
                "RMSE=\(rmse), max=\(maxError), threshold=2e-5",
                terminator: "\n"
            )
        }
    }

    private static let stages = [
        "input", "raw", "initial", "inhibitors",
        "diffused", "log", "densityPreGrain", "printed"
    ]

    private static func readBytes(
        _ path: URL, digest: String
    ) throws -> Data {
        let data = try Data(contentsOf: path)
        let actual = SHA256.hash(data: data)
            .map { String(format: "%02x", $0) }.joined()
        guard actual == digest else {
            throw Failure.invalid(
                "Python source fixture checksum changed: " +
                path.lastPathComponent
            )
        }
        return data
    }

    private static func reference(
        _ base: URL, sample: Sample, stage: String
    ) throws -> [Double] {
        guard let checksum = sample.sha256[stage] else {
            throw Failure.invalid("Missing source SHA256: \(stage)")
        }
        let path = base.appendingPathComponent(
            sample.name + "." + stage + ".f64le"
        )
        let data = try readBytes(path, digest: checksum)
        let count = sample.width * sample.height * 3
        guard data.count == count * 8 else {
            throw Failure.invalid(
                "\(sample.name) \(stage) invalid Float64 reference byte length"
            )
        }
        return data.withUnsafeBytes { raw -> [Double] in
            (0..<count).map { i in
                let word = raw.loadUnaligned(
                    fromByteOffset: i * 8, as: UInt64.self
                )
                return Double(bitPattern: UInt64(littleEndian: word))
            }
        }
    }

    private static func identityCube(_ n: Int) -> Data {
        let step = Float(1.0 / Double(n - 1))
        var values = [Float]()
        values.reserveCapacity(n * n * n * 4)
        for b in 0..<n {
            for g in 0..<n {
                for r in 0..<n {
                    values.append(contentsOf: [
                        Float(r) * step, Float(g) * step, Float(b) * step, 1.0
                    ])
                }
            }
        }
        return values.withUnsafeBufferPointer {
            Data(bytes: $0.baseAddress!, count: values.count * 4)
        }
    }

    static func evaluate(fixtures: URL) throws {
        let manifestURL = fixtures.appendingPathComponent("manifest.json")
        let manifest = try JSONDecoder().decode(
            Manifest.self, from: Data(contentsOf: manifestURL)
        )
        guard manifest.scope == "8bit-sRGB-source-spatial-DIR-identity-LUT-only",
              manifest.source == "src/spektrafilm/model/couplers.py",
              manifest.cases.count == 3 else {
            throw Failure.invalid("Wrong original Python source fixture scope")
        }
        let nine = identityCube(9)
        let seventeen = identityCube(17)
        var totalChannels = 0
        for c in manifest.cases {
            guard c.width > 0 && c.height > 0,
                  c.width <= 8192 && c.height <= 8192,
                  c.width <= 16_000_000 / c.height,
                  c.matrix.count == 9, c.densityMaximum.count == 3 else {
                throw Failure.invalid("Invalid original frame/film parameters")
            }
            guard let pngDigest = c.sha256["png"] else {
                throw Failure.invalid("Original source PNG checksum missing")
            }
            let png = try readBytes(
                fixtures.appendingPathComponent(c.name + ".png"),
                digest: pngDigest
            )
            // This calls the SAME 8-bit ImageIO ingestion as production,
            // not a test-only synthetic Float64 bypass.
            let decoded = try OriginalSourcePixelIO.decode(png)
            guard decoded.width == c.width && decoded.height == c.height else {
                throw Failure.invalid(
                    "\(c.name): ImageIO dimension/orientation mismatch"
                )
            }
            var decodedMetric = Metrics()
            try decodedMetric.compare(
                decoded.rgb, reference: try reference(
                    fixtures, sample: c, stage: "input"
                ), label: "\(c.name) actual ImageIO RGB source"
            )
            var stage = SpatialDIRStage(
                rawLogCube: nine,
                initialDensityCube: nine,
                correctedDensityCube: seventeen,
                printCube: nine,
                sourceCubeSize: 9,
                correctedCubeSize: 17,
                densityRanges: [1,1,1],
                densityMaximum: c.densityMaximum,
                logExposureSpans: [2,2,2],
                donorReceiverMatrix: c.matrix,
                positive: c.positive
            )
            stage.float64OpticalNodes = .identity(
                sourceSize: 9, correctedSize: 17
            )
            var settings = SpatialDIRSettings(enabled: true)
            settings.diffusionRadiusScale = c.radiusScale
            settings.tailWeight = c.tailWeight
            settings.referencePixelSizeUM = c.pixelUM
            settings.sourceConvolutionEnabled = true
            guard stage.valid && settings.valid else {
                throw Failure.invalid("Source stage or pixel settings invalid")
            }
            let rect = CGRect(x: 0, y: 0, width: c.width, height: c.height)
            let geometry = CIImage(
                color: CIColor(red: 0, green: 0, blue: 0)
            ).cropped(to: rect)
            var stagePixels = [String: [Double]]()
            _ = try SourceSpatialDIRConvolution.applyExactImagePath(
                to: geometry, stage: stage, settings: settings,
                grain: nil, stageObserver: nil,
                sourceRGBOverride: decoded.rgb,
                stageDoubleObserver: { name, pixels in
                    stagePixels[name] = pixels
                },
                suppressFinalCIImage: true
            )
            for name in stages.dropFirst() {
                guard let observed = stagePixels[name] else {
                    throw Failure.invalid("\(c.name) missing stage: \(name)")
                }
                var m = Metrics()
                try m.compare(
                    observed, reference: try reference(
                        fixtures, sample: c, stage: name
                    ), label: "\(c.name) \(name)"
                )
            }
            // Verify the actual public production API, not solely the stage
            // observer. The working geometry CIImage is never rendered.
            let printed = try OriginalSourcePixelIO.develop(
                decoded, stage: stage, settings: settings
            )
            var finalMetric = Metrics()
            try finalMetric.compare(
                printed.rgb, reference: try reference(
                    fixtures, sample: c, stage: "printed"
                ), label: "\(c.name) production Double print"
            )
            totalChannels += c.width * c.height * 3
            print("PASS source full-frame \(c.film) " +
                  "\(c.positive ? "positive" : "negative") " +
                  "\(c.width)x\(c.height)")
        }
        print(
            "PASS: \(manifest.cases.count) Python original source DIR " +
            "multi-size whole frames, \(totalChannels) RGB channels each " +
            "across 8 stages and production ImageIO/Double output. " +
            "NOT full film-to-print, RAW, Numba grain or iPhone certification."
        )
    }
}
